"use client";
import { useEffect, useState, useMemo } from "react";
import { 
  Table, 
  Tag, 
  Progress, 
  Select, 
  Card, 
  Badge, 
  Tooltip, 
  Modal, 
  Descriptions, 
  Button, 
  Input, 
  Segmented,
  Row,
  Col,
  Empty,
  Spin,
  Timeline
} from "antd";
import { 
  WarningOutlined, 
  CheckCircleOutlined, 
  ClockCircleOutlined, 
  BankOutlined, 
  CalendarOutlined, 
  ApartmentOutlined,
  ThunderboltOutlined,
  FileTextOutlined,
  CheckSquareOutlined,
  EyeOutlined,
  PieChartOutlined,
  TableOutlined,
  FieldTimeOutlined,
  SearchOutlined,
  FireOutlined,
  RiseOutlined,
  FlagOutlined
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { NhiemVuData } from "@/types";
import { 
  LOP_CONFIG, 
  TRANG_THAI_CONFIG, 
  UU_TIEN_CONFIG, 
  PHUONG_AN_CONFIG, 
  formatDate, 
  isOverdue, 
  getDaysRemaining 
} from "@/lib/utils";
import { 
  ResponsiveContainer, 
  PieChart, 
  Pie, 
  Cell, 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  Tooltip as RechartsTooltip, 
  Legend 
} from "recharts";

const { Search } = Input;

export default function LoTrinhPage() {
  const [data, setData] = useState<NhiemVuData[]>([]);
  const [loading, setLoading] = useState(true);
  const [viewMode, setViewMode] = useState<"dashboard" | "table" | "timeline">("dashboard");
  const [filterLop, setFilterLop] = useState<string>("");
  const [filterTrangThai, setFilterTrangThai] = useState<string>("");
  const [filterUuTien, setFilterUuTien] = useState<string>("");
  const [filterDonVi, setFilterDonVi] = useState<string>("");
  const [searchQuery, setSearchQuery] = useState("");
