          {selectedItem.donVi?.ten || selectedItem.chuQuan || "Chưa xác định"}
        </div>
      </Descriptions.Item>

      <Descriptions.Item label="Năm triển khai">
        <div className="flex items-center gap-2 text-gray-700">
          <CalendarOutlined className="text-gray-400" />
          <span>{selectedItem.namTrienKhai ? `Năm ${selectedItem.namTrienKhai}` : "Chưa xác định"}</span>
        </div>
      </Descriptions.Item>

      {tenMienAttr && (
        <Descriptions.Item label="Tên miền / Đường dẫn">
          <div className="flex items-center gap-2">
            <GlobalOutlined className="text-blue-500" />
            <a
              href={tenMienAttr.value.startsWith("http") ? tenMienAttr.value : `https://${tenMienAttr.value}`}
              target="_blank"
              rel="noreferrer"
              className="text-blue-600 hover:underline font-mono text-xs"
            >
              {tenMienAttr.value}
            </a>
          </div>
        </Descriptions.Item>
      )}

      {otherAttributes.map((attr, idx) => (
        <Descriptions.Item key={idx} label={attr.key}>
          <span className="whitespace-pre-wrap text-gray-700">{attr.value}</span>
        </Descriptions.Item>
      ))}
    </Descriptions>

