"use client";
import { useState, useEffect } from "react";
import Link from "next/link";
import { Card, Tag, Badge, Tooltip, Modal, Button, Spin, Row, Col } from "antd";
import {
  ApartmentOutlined,
  DatabaseOutlined,
  GlobalOutlined,
  BankOutlined,
  SafetyCertificateOutlined,
  ThunderboltOutlined,
  RightOutlined,
  FileProtectOutlined,
  CloudServerOutlined,
  MobileOutlined,
  NodeIndexOutlined,
  LockOutlined,
  CheckCircleOutlined,
  WarningOutlined,
  DesktopOutlined,
  TeamOutlined,
  InfoCircleOutlined
} from "@ant-design/icons";
import { HeThongSoData, NhiemVuData } from "@/types";
import { LOP_CONFIG, TRANG_THAI_CONFIG } from "@/lib/utils";

interface FrameworkBlock {
  id: string;
  title: string;
  description: string;
  icon: React.ReactNode;
  lop: number;
  category: string;
  itemsMatch: (ht: HeThongSoData) => boolean;
  tasksMatch: (nv: NhiemVuData) => boolean;
  color: string;
  borderColor: string;
  bgColor: string;
}

export default function SoDoKhungKTSPage() {
  const [heThongs, setHeThongs] = useState<HeThongSoData[]>([]);
  const [nhiemVus, setNhiemVus] = useState<NhiemVuData[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedBlock, setSelectedBlock] = useState<FrameworkBlock | null>(null);

  useEffect(() => {
    Promise.all([
      fetch("/api/he-thong").then((r) => r.json()),
      fetch("/api/nhiem-vu").then((r) => r.json()),
    ])
      .then(([htData, nvData]) => {
        setHeThongs(Array.isArray(htData) ? htData : []);
        setNhiemVus(Array.isArray(nvData) ? nvData : []);
        setLoading(false);
      })
      .catch(() => {
        setHeThongs([]);
        setNhiemVus([]);
        setLoading(false);
      });
  }, []);

  // Define the architectural blocks based on QD 1425 / National Digital Architecture Framework PB 1.0
  const frameworkBlocks: Record<string, FrameworkBlock> = {
    // Top: Channels & Users
    kenh_dvc: {
      id: "kenh_dvc",
      title: "Cổng DVC & Một Cửa Điện Tử",
      description: "Cổng Dịch vụ công trực tuyến tỉnh kết nối Cổng DVC Quốc gia",
      icon: <GlobalOutlined />,
      lop: 4,
      category: "Kênh giao tiếp số",
      itemsMatch: (ht) => ht.lop === 4 || ht.ten.toLowerCase().includes("dịch vụ công") || ht.ten.toLowerCase().includes("một cửa"),
      tasksMatch: (nv) => nv.ma === "NV-04" || nv.lop === 4,
      color: "#c2410c",
      borderColor: "#fdba74",
      bgColor: "#fff7ed",
    },
    kenh_mobile: {
      id: "kenh_mobile",
      title: "Nền Tảng Di Động & Smart App",
      description: "Ứng dụng Vĩnh Long Smart, ứng dụng di động phục vụ người dân, doanh nghiệp",
      icon: <MobileOutlined />,
      lop: 4,
      category: "Kênh giao tiếp số",
      itemsMatch: (ht) => ht.ten.toLowerCase().includes("di động") || ht.ten.toLowerCase().includes("app") || ht.ten.toLowerCase().includes("smart"),
      tasksMatch: (nv) => nv.ma === "NV-07",
      color: "#ea580c",
      borderColor: "#fed7aa",
      bgColor: "#fffaf5",
    },
    kenh_dinhdanh: {
      id: "kenh_dinhdanh",
      title: "Định Danh Điện Tử & VNeID",
      description: "Tích hợp tài khoản định danh điện tử VNeID và xác thực người dùng",
      icon: <SafetyCertificateOutlined />,
      lop: 4,
      category: "Kênh giao tiếp số",
      itemsMatch: (ht) => ht.ten.toLowerCase().includes("định danh") || ht.ma === "DL-01",
      tasksMatch: (nv) => nv.ma === "NV-03",
      color: "#b45309",
      borderColor: "#fde68a",
      bgColor: "#fefce8",
    },

    // Layer 2: Business & Core Gov
    nghiep_vu_dieu_hanh: {
      id: "nghiep_vu_dieu_hanh",
      title: "Chỉ Đạo, Điều Hành & Văn Bản Số",
      description: "Hệ thống quản lý văn bản iOffice, họp không giấy e-Cabinet, báo cáo số",
      icon: <FileProtectOutlined />,
      lop: 3,
      category: "Nghiệp vụ chính quyền số",
      itemsMatch: (ht) => ht.ten.toLowerCase().includes("văn bản") || ht.ten.toLowerCase().includes("điều hành") || ht.ten.toLowerCase().includes("báo cáo"),
      tasksMatch: (nv) => nv.ten.toLowerCase().includes("văn bản"),
      color: "#15803d",
      borderColor: "#86efac",
      bgColor: "#f0fdf4",
    },
    nghiep_vu_tthc: {
      id: "nghiep_vu_tthc",
      title: "Giải Quyết Thủ Tục Hành Chính",
      description: "Quy trình số hóa hồ sơ TTHC, số hóa kết quả giải quyết TTHC toàn tỉnh",
      icon: <DesktopOutlined />,
      lop: 3,
      category: "Nghiệp vụ chính quyền số",
      itemsMatch: (ht) => ht.ten.toLowerCase().includes("thủ tục") || ht.ten.toLowerCase().includes("tthc"),
      tasksMatch: (nv) => nv.ma === "NV-04",
      color: "#047857",
      borderColor: "#6ee7b7",
      bgColor: "#ecfdf5",
    },

    // Layer 3: Department Applications & Silos
    app_nongnghiep: {
      id: "app_nongnghiep",
      title: "Khối Nông Nghiệp & PTNT (380+ CSDL)",
      description: "Hệ thống bản đồ canh tác, trạm quan trắc VnEmisoft, ATTP, truy xuất nguồn gốc, OCOP...",
      icon: <DatabaseOutlined />,
      lop: 3,
      category: "Ứng dụng & Dữ liệu chuyên ngành",
      itemsMatch: (ht) => ht.ma.startsWith("SNN-") || (ht.donVi?.ten || "").includes("Nông nghiệp"),
      tasksMatch: (nv) => false,
      color: "#166534",
      borderColor: "#4ade80",
      bgColor: "#dcfce7",
    },
    app_yte: {
      id: "app_yte",
      title: "Khối Y Tế & Sức Khỏe Số",
      description: "Hệ thống thông tin quản lý bệnh viện HIS, Bệnh án điện tử EMR, quản lý trạm y tế",
      icon: <ThunderboltOutlined />,
      lop: 3,
      category: "Ứng dụng & Dữ liệu chuyên ngành",
      itemsMatch: (ht) => ht.ma === "UD-03" || ht.ten.toLowerCase().includes("y tế") || ht.ten.toLowerCase().includes("his"),
      tasksMatch: (nv) => nv.ma === "NV-09",
      color: "#0e7490",
      borderColor: "#67e8f9",
      bgColor: "#ecfeff",
    },
    app_datdai: {
      id: "app_datdai",
      title: "Khối Tài Nguyên & Đất Đai",
      description: "CSDL Đất đai tỉnh kết nối nền tảng điều phối dữ liệu đất đai quốc gia (NDOP)",
      icon: <ApartmentOutlined />,
      lop: 2,
      category: "Ứng dụng & Dữ liệu chuyên ngành",
      itemsMatch: (ht) => ht.ma === "DL-02" || ht.ten.toLowerCase().includes("đất đai"),
      tasksMatch: (nv) => nv.ma === "NV-01",
      color: "#1d4ed8",
      borderColor: "#93c5fd",
      bgColor: "#eff6ff",
    },
    app_trolyao: {
      id: "app_trolyao",
      title: "Trợ Lý Ảo AI & Công Nghệ Số Mới",
      description: "Trợ lý ảo AI phục vụ cán bộ công chức và hỗ trợ người dân thực hiện DVC",
      icon: <ThunderboltOutlined />,
      lop: 3,
      category: "Ứng dụng & Dữ liệu chuyên ngành",
      itemsMatch: (ht) => ht.ten.toLowerCase().includes("trợ lý ảo") || ht.ten.toLowerCase().includes("ai"),
      tasksMatch: (nv) => nv.ma === "NV-08",
      color: "#6b21a8",
      borderColor: "#d8b4fe",
      bgColor: "#faf5ff",
    },

    // Layer 4: Integration & Sharing (LGSP / NDXP)
    tich_hop_lgsp: {
      id: "tich_hop_lgsp",
      title: "Trục Liên Thông Dữ Liệu LGSP / NDXP",
      description: "Nền tảng tích hợp, chia sẻ dữ liệu cấp tỉnh (LGSP) kết nối Trục Quốc gia (NDXP)",
      icon: <NodeIndexOutlined />,
      lop: 2,
      category: "Nền tảng tích hợp & chia sẻ",
      itemsMatch: (ht) => ht.ma === "DL-03" || ht.ten.toLowerCase().includes("lgsp") || ht.ten.toLowerCase().includes("chia sẻ"),
      tasksMatch: (nv) => nv.ma === "NV-04" || nv.ma === "NV-06",
      color: "#1e40af",
      borderColor: "#60a5fa",
      bgColor: "#dbeafe",
    },
    tich_hop_danhmuc: {
      id: "tich_hop_danhmuc",
      title: "Kho Dữ Liệu Dùng Chung & Master Data",
      description: "Từ điển dữ liệu dùng chung, kho dữ liệu tổng hợp phục vụ phân tích và điều hành",
      icon: <DatabaseOutlined />,
      lop: 2,
      category: "Nền tảng tích hợp & chia sẻ",
      itemsMatch: (ht) => ht.ma.startsWith("DL-") || ht.ten.toLowerCase().includes("dân cư") || ht.ten.toLowerCase().includes("danh mục"),
      tasksMatch: (nv) => nv.ma === "NV-06" || nv.ma === "NV-03",
      color: "#2563eb",
      borderColor: "#93c5fd",
      bgColor: "#eff6ff",
    },

    // Layer 5: Infrastructure & Cloud (IDC / Network / IOC)
    ha_tang_idc: {
      id: "ha_tang_idc",
      title: "Trung Tâm Dữ Liệu & Điện Toán Đám Mây (IDC)",
      description: "Trung tâm tích hợp dữ liệu tỉnh, chuyển đổi sang kiến trúc Cloud kết nối IDC Quốc gia",
      icon: <CloudServerOutlined />,
      lop: 1,
      category: "Hạ tầng số",
      itemsMatch: (ht) => ht.ma === "HT-02" || ht.ten.toLowerCase().includes("idc") || ht.ten.toLowerCase().includes("trung tâm tích hợp"),
      tasksMatch: (nv) => nv.ma === "NV-02",
      color: "#4c1d95",
      borderColor: "#c084fc",
      bgColor: "#f3e8ff",
    },
    ha_tang_wan: {
      id: "ha_tang_wan",
      title: "Mạng Truyền Số Liệu Chuyên Dùng (TSLCD)",
      description: "Hạ tầng mạng WAN tỉnh kết nối 100% cơ quan cấp tỉnh, huyện, xã",
      icon: <NodeIndexOutlined />,
      lop: 1,
      category: "Hạ tầng số",
      itemsMatch: (ht) => ht.ma === "HT-01" || ht.ten.toLowerCase().includes("wan") || ht.ten.toLowerCase().includes("mạng"),
      tasksMatch: (nv) => false,
      color: "#581c87",
      borderColor: "#d8b4fe",
      bgColor: "#faf5ff",
    },

    // Cross-cutting Pillars
    tru_attt_soc: {
      id: "tru_attt_soc",
      title: "Trung Tâm Giám Sát ATTT (SOC Tỉnh)",
      description: "Mô hình bảo đảm an toàn thông tin 4 lớp, kết nối SOC Quốc gia của Bộ Công an",
      icon: <LockOutlined />,
      lop: 1,
      category: "An toàn thông tin",
      itemsMatch: (ht) => ht.ma === "HT-03" || ht.ten.toLowerCase().includes("soc") || ht.ten.toLowerCase().includes("an toàn"),
      tasksMatch: (nv) => nv.ma === "NV-05",
      color: "#991b1b",
      borderColor: "#f87171",
      bgColor: "#fef2f2",
    },
  };

  const getMatchedItems = (block: FrameworkBlock) => {
    return heThongs.filter(block.itemsMatch);
  };

  const getMatchedTasks = (block: FrameworkBlock) => {
    return nhiemVus.filter(block.tasksMatch);
  };

  const renderBlockCard = (blockKey: string) => {
    const block = frameworkBlocks[blockKey];
    if (!block) return null;
    const items = getMatchedItems(block);
    const tasks = getMatchedTasks(block);
    const hasUpgrade = items.some((i) => i.trangThai === "can-nang-cap") || tasks.length > 0;

    return (
      <div
        onClick={() => setSelectedBlock(block)}
        className="p-3.5 rounded-xl border-2 transition-all cursor-pointer hover:shadow-lg hover:-translate-y-0.5 flex flex-col justify-between group"
        style={{
          borderColor: block.borderColor,
          backgroundColor: block.bgColor,
        }}
      >
        <div>
          <div className="flex justify-between items-start mb-1.5">
            <div className="flex items-center gap-1.5 font-bold text-sm" style={{ color: block.color }}>
              <span className="text-base">{block.icon}</span>
              <span className="line-clamp-1">{block.title}</span>
            </div>
            {hasUpgrade && (
              <span className="bg-amber-100 text-amber-950 border border-amber-400 font-bold text-[10px] px-1.5 py-0.5 rounded-full shrink-0">
                Có lộ trình
              </span>
            )}
          </div>
          <div className="text-xs text-gray-600 line-clamp-2 leading-relaxed mb-2.5">
            {block.description}
          </div>
        </div>

        <div className="flex justify-between items-center pt-2 border-t border-black/5 text-xs">
          <span className="font-semibold text-gray-700 bg-white/80 px-2 py-0.5 rounded border border-black/5">
            {items.length > 0 ? `${items.length} hệ thống/CSDL` : "Quy chuẩn mục tiêu"}
          </span>
          <span className="font-bold flex items-center gap-0.5 group-hover:translate-x-0.5 transition-transform" style={{ color: block.color }}>
            Chi tiết <RightOutlined className="text-[10px]" />
          </span>
        </div>
      </div>
    );
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center min-h-[60vh]">
        <Spin size="large" />
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto space-y-6 pb-16">
      {/* Header Banner */}
      <div className="bg-gradient-to-r from-blue-950 via-slate-900 to-indigo-950 text-white p-6 rounded-2xl shadow-md flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <div className="flex items-center gap-2 mb-2">
            <span className="bg-amber-400/30 text-amber-200 border border-amber-400/40 text-xs px-2.5 py-0.5 rounded-full font-bold flex items-center gap-1">
              <ApartmentOutlined /> Chuẩn QĐ 1425/QĐ-TTg
            </span>
            <span className="text-xs text-blue-300">Phiên bản 1.0 — Khung Kiến Trúc Chính Quyền Số Tỉnh Vĩnh Long</span>
          </div>
          <h1 className="text-2xl font-bold tracking-tight text-white m-0">
            Sơ Đồ Khung Kiến Trúc Tổng Thể Chính Quyền Số
          </h1>
          <p className="text-sm text-blue-200/90 mt-1 mb-0 max-w-2xl">
            Mô hình phân tầng kiến trúc số hóa toàn diện từ Kênh giao tiếp, Nghiệp vụ, Ứng dụng chuyên ngành, Trục tích hợp LGSP đến Trung tâm Dữ liệu và An toàn thông tin.
          </p>
        </div>

        <div className="flex gap-2">
          <Link href="/kts/hien-trang">
            <Button className="bg-white/15 border-white/30 text-white hover:bg-white/25">
              Xem Hiện Trạng (389 HT)
            </Button>
          </Link>
          <Link href="/kts/lo-trinh">
            <Button type="primary" className="bg-blue-600 border-blue-500 font-semibold">
              Xem Lộ Trình (9 NV)
            </Button>
          </Link>
        </div>
      </div>

      {/* ARCHITECTURE BLUEPRINT DIAGRAM */}
      <Card className="shadow-md rounded-2xl border-gray-200 overflow-hidden p-2">
        <div className="text-center mb-6">
          <div className="inline-block bg-slate-100 text-slate-800 border border-slate-300 px-4 py-1 rounded-full text-xs font-bold uppercase tracking-wider">
            🏛️ MÔ HÌNH KIẾN TRÚC TỔNG THỂ PHÂN TẦNG (BLUEPRINT)
          </div>
          <div className="text-xs text-gray-500 mt-1">
