  id: string;
  title: string;
  subtitle: string;
  description: string;
  icon: React.ReactNode;
  lop: number;
  category: string;
  itemsMatch: (ht: HeThongSoData) => boolean;
  tasksMatch: (nv: NhiemVuData) => boolean;
  color: string;
  accentBg: string;
}

