                  <span>2. Tiêu chuẩn & Quy chuẩn</span>
                </div>
                <ul className="text-xs text-slate-600 space-y-2 pl-3.5 list-disc m-0">
                  <li>Kiến trúc số dùng chung</li>
                  <li>Quy chế chia sẻ dữ liệu</li>
                  <li>Chuẩn dữ liệu mở & API</li>
                  <li>Định mức KT - kỹ thuật</li>
                </ul>
              </div>
            </div>

            <div className="pt-3 border-t border-slate-200 text-xs text-slate-500 text-center font-bold uppercase tracking-wider">
              Khung Thể Chế & Chuẩn Hóa
            </div>
          </div>

          {/* ========================================================================= */}
          {/* TRUNG TÂM: 04 LỚP KIẾN TRÚC CHUẨN QUỐC GIA (TOP-DOWN: LỚP 4 -> LỚP 1) */}
          {/* ========================================================================= */}
          <div className="xl:col-span-8 space-y-4">

            {/* ------------------------------------------------------------- */}
            {/* LỚP 4: KÊNH TƯƠNG TÁC VÀ ĐO LƯỜNG HIỆU QUẢ */}
            {/* ------------------------------------------------------------- */}
            <div className="bg-amber-50/50 rounded-2xl border border-amber-200 p-4 shadow-2xs">
              <div className="flex items-center justify-between mb-3 px-1">
                <span className="font-bold text-xs md:text-sm uppercase tracking-wide text-amber-950 flex items-center gap-2">
                  <TeamOutlined className="text-amber-600 text-base" /> LỚP 4: KÊNH TƯƠNG TÁC & ĐO LƯỜNG HIỆU QUẢ (OMNI-CHANNEL & KPIS)
                </span>
                <span className="text-xs text-amber-900 font-bold bg-amber-100/90 px-3 py-1 rounded-md border border-amber-200">
                  Người dân • Doanh nghiệp • Cán bộ CCVC
                </span>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
                {renderSpaciousCard("lop4_dvc")}
                {renderSpaciousCard("lop4_app_mobile")}
                {renderSpaciousCard("lop4_portal")}
                {renderSpaciousCard("lop4_kpi_metric")}
              </div>
            </div>

            {/* ------------------------------------------------------------- */}
            {/* LỚP 3: ỨNG DỤNG VÀ NGHIỆP VỤ DÙNG CHUNG */}
            {/* ------------------------------------------------------------- */}
            <div className="bg-emerald-50/40 rounded-2xl border border-emerald-200 p-4 shadow-2xs space-y-3">
              <div className="flex items-center justify-between px-1">
                <span className="font-bold text-xs md:text-sm uppercase tracking-wide text-emerald-950 flex items-center gap-2">
                  <DesktopOutlined className="text-emerald-600 text-base" /> LỚP 3: ỨNG DỤNG VÀ NGHIỆP VỤ DÙNG CHUNG (389+ HỆ THỐNG & CSDL)
                </span>
                <span className="text-xs text-emerald-900 font-bold bg-emerald-100/90 px-3 py-1 rounded-md border border-emerald-200">
                  Tổ chức 2 Nhánh song song: Chính quyền số VS. Kinh tế số & Xã hội số
                </span>
              </div>

              {/* 2 Parallel Clean Sections */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">

                {/* Nhánh 1: Chính quyền số */}
                <div className="bg-white/90 p-3.5 rounded-xl border border-emerald-200 space-y-3">
                  <div className="flex items-center justify-between px-1 pb-2 border-b border-slate-100">
                    <span className="font-bold text-xs md:text-sm text-emerald-900 flex items-center gap-1.5">
                      🏛️ NHÁNH 1: CHÍNH QUYỀN SỐ
                    </span>
                    <span className="text-xs text-slate-500 font-medium">(Nội bộ & TTHC)</span>
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    {renderSpaciousCard("lop3_chidao_dieuhanh")}
                    {renderSpaciousCard("lop3_tthc_sohoa")}
                    {renderSpaciousCard("lop3_ioc_tinh")}
                    {renderSpaciousCard("lop3_nghiepvu_chuyennganh")}
                  </div>
                </div>

                {/* Nhánh 2: Kinh tế số & Xã hội số */}
                <div className="bg-white/90 p-3.5 rounded-xl border border-emerald-200 space-y-3">
                  <div className="flex items-center justify-between px-1 pb-2 border-b border-slate-100">
                    <span className="font-bold text-xs md:text-sm text-emerald-900 flex items-center gap-1.5">
                      🌾 NHÁNH 2: KINH TẾ SỐ & XÃ HỘI SỐ
                    </span>
                    <span className="text-xs text-slate-500 font-medium">(Phát triển ngành & Đời sống)</span>
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    {renderSpaciousCard("lop3_nongnghiep_so")}
                    {renderSpaciousCard("lop3_yte_so")}
                    {renderSpaciousCard("lop3_datdai_tnmt")}
                    {renderSpaciousCard("lop3_dothi_kinhte")}
                  </div>
                </div>

              </div>
            </div>

            {/* ------------------------------------------------------------- */}
            {/* LỚP 2: DỮ LIỆU VÀ NỀN TẢNG LÕI */}
            {/* ------------------------------------------------------------- */}
            <div className="bg-blue-50/50 rounded-2xl border border-blue-200 p-4 shadow-2xs">
              <div className="flex items-center justify-between mb-3 px-1">
                <span className="font-bold text-xs md:text-sm uppercase tracking-wide text-blue-950 flex items-center gap-2">
                  <NodeIndexOutlined className="text-blue-600 text-base" /> LỚP 2: DỮ LIỆU VÀ NỀN TẢNG LÕI (LGSP / NDXP • MASTER DATA • CSDL QUỐC GIA)
                </span>
                <span className="text-xs text-blue-900 font-bold bg-blue-100/90 px-3 py-1 rounded-md border border-blue-200">
                  Trục liên thông • Dữ liệu dùng chung • Nền tảng lõi
                </span>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
                {renderSpaciousCard("lop2_lgsp_ndxp")}
                {renderSpaciousCard("lop2_kho_dulieu_master")}
                {renderSpaciousCard("lop2_csdl_quocgia")}
                {renderSpaciousCard("lop2_nentang_loi")}
              </div>
            </div>

            {/* ------------------------------------------------------------- */}
            {/* LỚP 1: HẠ TẦNG SỐ VÀ AN NINH MẠNG DÙNG CHUNG */}
            {/* ------------------------------------------------------------- */}
            <div className="bg-purple-50/50 rounded-2xl border border-purple-200 p-4 shadow-2xs">
              <div className="flex items-center justify-between mb-3 px-1">
                <span className="font-bold text-xs md:text-sm uppercase tracking-wide text-purple-950 flex items-center gap-2">
                  <CloudServerOutlined className="text-purple-600 text-base" /> LỚP 1: HẠ TẦNG SỐ VÀ AN NINH MẠNG DÙNG CHUNG (CLOUD • TSLCD • SOC 4 LỚP)
                </span>
                <span className="text-xs text-purple-900 font-bold bg-purple-100/90 px-3 py-1 rounded-md border border-purple-200">
                  IDC Cloud • Mạng TSLCD • Giám sát ATTT 24/7
                </span>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
                {renderSpaciousCard("lop1_idc_cloud")}
                {renderSpaciousCard("lop1_mang_tslcd")}
                {renderSpaciousCard("lop1_soc_anm")}
                {renderSpaciousCard("lop1_iot_bien")}
              </div>
            </div>

          </div>

          {/* ========================================================================= */}
          {/* CỘT PHẢI: 2 THÀNH PHẦN XUYÊN SUỐT (AI FIRST & DATA-CENTRIC) */}
          {/* ========================================================================= */}
          <div className="xl:col-span-2 bg-indigo-50/80 rounded-2xl border border-indigo-200 p-4 flex flex-col justify-between space-y-4">
            <div className="space-y-4">
              <div className="flex items-center gap-2 font-bold text-indigo-950 text-xs md:text-sm border-b border-indigo-200 pb-2.5">
                <ThunderboltOutlined className="text-indigo-600 text-base" />
                <span>THÀNH PHẦN XUYÊN SUỐT (III & IV)</span>
              </div>

              {/* 3. AI First */}
              <div className="bg-white p-3.5 rounded-xl border border-indigo-200/90 shadow-2xs">
                <div className="font-bold text-indigo-950 text-xs md:text-sm flex items-center gap-1.5 mb-2 text-indigo-900">
                  <RobotOutlined className="text-indigo-600" />
                  <span>3. Ưu tiên AI (AI First)</span>
                </div>
                <ul className="text-xs text-slate-600 space-y-2 pl-3.5 list-disc m-0">
                  <li>Trợ lý ảo AI CCVC</li>
                  <li>Trợ lý ảo hỗ trợ DVC</li>
                  <li>Tự động bóc tách hồ sơ</li>
                  <li>Dự báo & hỗ trợ điều hành</li>
                </ul>
              </div>

              {/* 4. Data Centric */}
              <div className="bg-white p-3.5 rounded-xl border border-indigo-200/90 shadow-2xs">
                <div className="font-bold text-indigo-950 text-xs md:text-sm flex items-center gap-1.5 mb-2 text-indigo-900">
                  <DatabaseOutlined className="text-indigo-600" />
                  <span>4. Dữ liệu trung tâm</span>
                </div>
                <ul className="text-xs text-slate-600 space-y-2 pl-3.5 list-disc m-0">
                  <li>Dữ liệu "Đúng-Đủ-Sạch-Sống"</li>
                  <li>Mở và chia sẻ mặc định</li>
                  <li>Xóa bỏ cát cứ dữ liệu</li>
                  <li>Khai thác giá trị dữ liệu số</li>
                </ul>
              </div>
            </div>

            <div className="pt-3 border-t border-indigo-200 text-xs text-indigo-700 text-center font-bold uppercase tracking-wider">
              Động Lực Công Nghệ & Dữ Liệu
            </div>
          </div>

        </div>
      </div>

      {/* DETAIL MODAL WHEN CLICKING ANY BLOCK */}
      <Modal
        title={
          <div className="flex items-center gap-2 pr-6">
            <span className="text-xl" style={{ color: selectedBlock?.color }}>{selectedBlock?.icon}</span>
            <span className="font-bold text-base text-gray-800">{selectedBlock?.title}</span>
          </div>
        }
        open={!!selectedBlock}
        onCancel={() => setSelectedBlock(null)}
        footer={[
          <Button key="close" type="primary" onClick={() => setSelectedBlock(null)}>
            Đóng
          </Button>,
        ]}
        width={750}
        destroyOnHidden
      >
        {selectedBlock && (
          <div className="space-y-4 mt-3">
            <div className="bg-slate-50 p-3 rounded-lg border border-slate-200 text-xs text-gray-700 leading-relaxed">
              <b>Phân loại kiến trúc:</b> <Tag color="blue">{selectedBlock.category}</Tag>
              <div className="mt-1">{selectedBlock.description}</div>
            </div>

            {/* Nhiệm vụ lộ trình liên quan */}
            <div>
              <div className="font-bold text-gray-800 text-sm mb-2 flex items-center gap-1.5">
                <ThunderboltOutlined className="text-amber-500" />
                <span>Nhiệm vụ & Đề án Lộ trình liên quan ({getMatchedTasks(selectedBlock).length}):</span>
              </div>
              {getMatchedTasks(selectedBlock).length > 0 ? (
                <div className="space-y-2">
                  {getMatchedTasks(selectedBlock).map((nv) => (
                    <div key={nv.id} className="p-3 bg-amber-50/60 rounded-lg border border-amber-200 flex justify-between items-center">
                      <div>
                        <div className="font-semibold text-gray-800 text-xs">
                          <span className="font-mono bg-amber-100 text-amber-800 px-1.5 py-0.5 rounded mr-1.5">{nv.ma}</span>
                          {nv.ten}
                        </div>
                        <div className="text-[11px] text-gray-500 mt-1">
                          Chủ trì: {nv.donViChuTri?.ten || "UBND tỉnh"} • Hạn: {nv.thoiHan ? new Date(nv.thoiHan).toLocaleDateString("vi-VN") : "—"}
                        </div>
                      </div>
                      <span className="font-bold text-xs text-blue-600 bg-white px-2 py-1 rounded border border-blue-200">
                        {nv.tienDo}%
                      </span>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-xs text-gray-400 italic bg-gray-50 p-2 rounded">
                  (Khối này hiện đang vận hành ổn định, không có dự án nâng cấp quy mô lớn trong lộ trình hiện tại)
                </div>
              )}
            </div>

            {/* Danh sách hệ thống số hiện trạng */}
            <div>
              <div className="font-bold text-gray-800 text-sm mb-2 flex items-center gap-1.5">
                <DatabaseOutlined className="text-blue-500" />
                <span>Hệ thống số & CSDL Hiện trạng thuộc khối này ({getMatchedItems(selectedBlock).length}):</span>
              </div>
              {getMatchedItems(selectedBlock).length > 0 ? (
                <div className="max-h-60 overflow-y-auto space-y-1.5 pr-1">
                  {getMatchedItems(selectedBlock).slice(0, 30).map((ht) => (
                    <div key={ht.id} className="p-2 bg-white rounded border border-gray-200 hover:border-blue-300 text-xs flex justify-between items-center">
                      <div className="flex-1 pr-2">
                        <span className="font-mono font-bold text-slate-800 bg-slate-200 px-1.5 py-0.5 rounded mr-1.5 text-[10px]">
                          {ht.ma}
                        </span>
                        <span className="font-medium text-gray-800">{ht.ten}</span>
                        <div className="text-[10px] text-gray-400 mt-0.5">
                          {ht.donVi?.ten || ht.chuQuan || "Chưa xác định"} {ht.namTrienKhai ? `• Năm ${ht.namTrienKhai}` : ""}
                        </div>
                      </div>
                      <span className={`text-[10px] font-bold px-2 py-0.5 rounded border ${TRANG_THAI_CONFIG[ht.trangThai]?.badgeClass || ""}`}>
                        {TRANG_THAI_CONFIG[ht.trangThai]?.label || ht.trangThai}
                      </span>
                    </div>
                  ))}
                  {getMatchedItems(selectedBlock).length > 30 && (
                    <div className="text-center text-xs text-blue-600 py-2">
                      ...và còn {getMatchedItems(selectedBlock).length - 30} CSDL/phần mềm chuyên ngành khác.
                    </div>
                  )}
                </div>
              ) : (
                <div className="text-xs text-gray-400 italic bg-gray-50 p-2 rounded">
                  (Khối này đóng vai trò quy chuẩn mục tiêu kết nối liên thông)
                </div>
              )}
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
}

