          {/* ========================================================================= */}
          <div className="xl:col-span-8 space-y-3.5">

            {/* ------------------------------------------------------------- */}
            {/* LỚP 4: KÊNH TƯƠNG TÁC VÀ ĐO LƯỜNG HIỆU QUẢ */}
            {/* ------------------------------------------------------------- */}
            <div className="bg-amber-50/50 rounded-2xl border border-amber-200 p-3 shadow-2xs">
              <div className="flex items-center justify-between mb-2 px-1">
                <span className="font-bold text-xs uppercase tracking-wide text-amber-950 flex items-center gap-1.5">
                  <TeamOutlined className="text-amber-600" /> LỚP 4: KÊNH TƯƠNG TÁC & ĐO LƯỜNG HIỆU QUẢ
                </span>
                <span className="text-[10px] text-amber-900 font-semibold bg-amber-100/90 px-2.5 py-0.5 rounded border border-amber-200">
