            </div>

            {/* ------------------------------------------------------------- */}
            {/* LỚP 3: ỨNG DỤNG VÀ NGHIỆP VỤ DÙNG CHUNG */}
            {/* ------------------------------------------------------------- */}
            <div className="bg-emerald-50/40 rounded-2xl border border-emerald-200 p-3 shadow-2xs space-y-2.5">
              <div className="flex items-center justify-between px-1">
                <span className="font-bold text-xs uppercase tracking-wide text-emerald-950 flex items-center gap-1.5">
                  <DesktopOutlined className="text-emerald-600" /> LỚP 3: ỨNG DỤNG VÀ NGHIỆP VỤ DÙNG CHUNG (389+ HỆ THỐNG)
                </span>
                <span className="text-[10px] text-emerald-900 font-semibold bg-emerald-100/90 px-2.5 py-0.5 rounded border border-emerald-200">
                  2 Nhánh song song
                </span>
              </div>

              {/* 2 Parallel Clean Sections */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">

                {/* Nhánh 1: Chính quyền số */}
                <div className="bg-white/90 p-2.5 rounded-xl border border-emerald-200 space-y-2">
                  <div className="flex items-center justify-between px-1 pb-1.5 border-b border-slate-100">
                    <span className="font-bold text-xs text-emerald-950 flex items-center gap-1">
                      🏛️ CHÍNH QUYỀN SỐ
                    </span>
                    <span className="text-[10px] text-slate-400 font-medium">(Nội bộ & TTHC)</span>
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                    {renderMinimalCard("lop3_chidao_dieuhanh")}
                    {renderMinimalCard("lop3_tthc_sohoa")}
                    {renderMinimalCard("lop3_ioc_tinh")}
                    {renderMinimalCard("lop3_nghiepvu_chuyennganh")}
                  </div>
                </div>

                {/* Nhánh 2: Kinh tế số & Xã hội số */}
                <div className="bg-white/90 p-2.5 rounded-xl border border-emerald-200 space-y-2">
                  <div className="flex items-center justify-between px-1 pb-1.5 border-b border-slate-100">
                    <span className="font-bold text-xs text-emerald-950 flex items-center gap-1">
                      🌾 KINH TẾ SỐ & XÃ HỘI SỐ
                    </span>
                    <span className="text-[10px] text-slate-400 font-medium">(Ngành & Đời sống)</span>
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                    {renderMinimalCard("lop3_nongnghiep_so")}
                    {renderMinimalCard("lop3_yte_so")}
                    {renderMinimalCard("lop3_datdai_tnmt")}
                    {renderMinimalCard("lop3_dothi_kinhte")}
                  </div>
                </div>

              </div>
            </div>

            {/* ------------------------------------------------------------- */}
            {/* LỚP 2: DỮ LIỆU VÀ NỀN TẢNG LÕI */}
            {/* ------------------------------------------------------------- */}
            <div className="bg-blue-50/50 rounded-2xl border border-blue-200 p-3 shadow-2xs">
              <div className="flex items-center justify-between mb-2 px-1">
                <span className="font-bold text-xs uppercase tracking-wide text-blue-950 flex items-center gap-1.5">
                  <NodeIndexOutlined className="text-blue-600" /> LỚP 2: DỮ LIỆU VÀ NỀN TẢNG LÕI (LGSP / NDXP • MASTER DATA)
                </span>
                <span className="text-[10px] text-blue-900 font-semibold bg-blue-100/90 px-2.5 py-0.5 rounded border border-blue-200">
                  Trục liên thông • CSDL dùng chung
                </span>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-2.5">
                {renderMinimalCard("lop2_lgsp_ndxp")}
                {renderMinimalCard("lop2_kho_dulieu_master")}
                {renderMinimalCard("lop2_csdl_quocgia")}
                {renderMinimalCard("lop2_nentang_loi")}
              </div>
            </div>

            {/* ------------------------------------------------------------- */}
            {/* LỚP 1: HẠ TẦNG SỐ VÀ AN NINH MẠNG DÙNG CHUNG */}
            {/* ------------------------------------------------------------- */}
            <div className="bg-purple-50/50 rounded-2xl border border-purple-200 p-3 shadow-2xs">
              <div className="flex items-center justify-between mb-2 px-1">
                <span className="font-bold text-xs uppercase tracking-wide text-purple-950 flex items-center gap-1.5">
                  <CloudServerOutlined className="text-purple-600" /> LỚP 1: HẠ TẦNG SỐ VÀ AN NINH MẠNG DÙNG CHUNG (CLOUD • SOC 4 LỚP)
                </span>
                <span className="text-[10px] text-purple-900 font-semibold bg-purple-100/90 px-2.5 py-0.5 rounded border border-purple-200">
                  IDC Cloud • Mạng TSLCD • SOC 24/7
                </span>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-2.5">
                {renderMinimalCard("lop1_idc_cloud")}
                {renderMinimalCard("lop1_mang_tslcd")}
                {renderMinimalCard("lop1_soc_anm")}
                {renderMinimalCard("lop1_iot_bien")}
              </div>
            </div>

          </div>

          {/* ========================================================================= */}
          {/* CỘT PHẢI: 2 THÀNH PHẦN XUYÊN SUỐT (AI FIRST & DATA-CENTRIC) */}
          {/* ========================================================================= */}
          <div className="xl:col-span-2 bg-indigo-50/80 rounded-2xl border border-indigo-200 p-3.5 flex flex-col justify-between space-y-3">
            <div className="space-y-3">
              <div className="flex items-center gap-1.5 font-bold text-indigo-950 text-xs border-b border-indigo-200 pb-2">
                <ThunderboltOutlined className="text-indigo-600" />
                <span>THÀNH PHẦN XUYÊN SUỐT</span>
              </div>

              {/* 3. AI First */}
              <div className="bg-white p-3 rounded-xl border border-indigo-200/90 shadow-2xs">
                <div className="font-bold text-indigo-950 text-xs flex items-center gap-1 mb-1.5">
                  <RobotOutlined className="text-indigo-600" />
                  <span>3. Ưu tiên AI (AI First)</span>
                </div>
                <ul className="text-[11px] text-slate-600 space-y-1.5 pl-3 list-disc m-0">
                  <li>Trợ lý ảo AI cán bộ</li>
                  <li>Trợ lý ảo hỗ trợ DVC</li>
                  <li>Tự động hóa bóc tách</li>
                </ul>
              </div>

              {/* 4. Data Centric */}
              <div className="bg-white p-3 rounded-xl border border-indigo-200/90 shadow-2xs">
                <div className="font-bold text-indigo-950 text-xs flex items-center gap-1 mb-1.5">
                  <DatabaseOutlined className="text-indigo-600" />
                  <span>4. Dữ liệu trung tâm</span>
                </div>
                <ul className="text-[11px] text-slate-600 space-y-1.5 pl-3 list-disc m-0">
                  <li>Đúng - Đủ - Sạch - Sống</li>
                  <li>Chia sẻ mặc định</li>
                  <li>Xóa bỏ cát cứ dữ liệu</li>
                </ul>
              </div>
            </div>

            <div className="pt-2 border-t border-indigo-200 text-[10px] text-indigo-700 text-center font-bold uppercase tracking-wider">
              Động Lực Số
            </div>
          </div>

        </div>
      </div>

      {/* DETAIL MODAL WHEN CLICKING ANY BLOCK */}
      <Modal
        title={
          <div className="flex items-center gap-2 pr-6">
            <span className="text-xl" style={{ color: selectedBlock?.color }}>{selectedBlock?.icon}</span>
            <span className="font-bold text-base text-gray-800">{selectedBlock?.title}</span>
          </div>
        }
        open={!!selectedBlock}
        onCancel={() => setSelectedBlock(null)}
        footer={[
          <Button key="close" type="primary" onClick={() => setSelectedBlock(null)}>
            Đóng
          </Button>,
        ]}
        width={750}
        destroyOnHidden
      >
        {selectedBlock && (
          <div className="space-y-4 mt-3">
            <div className="bg-slate-50 p-3 rounded-lg border border-slate-200 text-xs text-gray-700 leading-relaxed">
              <b>Phân loại kiến trúc:</b> <Tag color="blue">{selectedBlock.category}</Tag>
              <div className="mt-1">{selectedBlock.description}</div>
            </div>

            {/* Nhiệm vụ lộ trình liên quan */}
            <div>
              <div className="font-bold text-gray-800 text-sm mb-2 flex items-center gap-1.5">
                <ThunderboltOutlined className="text-amber-500" />
                <span>Nhiệm vụ & Đề án Lộ trình liên quan ({getMatchedTasks(selectedBlock).length}):</span>
              </div>
              {getMatchedTasks(selectedBlock).length > 0 ? (
                <div className="space-y-2">
                  {getMatchedTasks(selectedBlock).map((nv) => (
                    <div key={nv.id} className="p-3 bg-amber-50/60 rounded-lg border border-amber-200 flex justify-between items-center">
                      <div>
                        <div className="font-semibold text-gray-800 text-xs">
                          <span className="font-mono bg-amber-100 text-amber-800 px-1.5 py-0.5 rounded mr-1.5">{nv.ma}</span>
                          {nv.ten}
                        </div>
                        <div className="text-[11px] text-gray-500 mt-1">
                          Chủ trì: {nv.donViChuTri?.ten || "UBND tỉnh"} • Hạn: {nv.thoiHan ? new Date(nv.thoiHan).toLocaleDateString("vi-VN") : "—"}
                        </div>
                      </div>
                      <span className="font-bold text-xs text-blue-600 bg-white px-2 py-1 rounded border border-blue-200">
                        {nv.tienDo}%
                      </span>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-xs text-gray-400 italic bg-gray-50 p-2 rounded">
                  (Khối này hiện đang vận hành ổn định, không có dự án nâng cấp quy mô lớn trong lộ trình hiện tại)
                </div>
              )}
            </div>

            {/* Danh sách hệ thống số hiện trạng */}
            <div>
              <div className="font-bold text-gray-800 text-sm mb-2 flex items-center gap-1.5">
                <DatabaseOutlined className="text-blue-500" />
                <span>Hệ thống số & CSDL Hiện trạng thuộc khối này ({getMatchedItems(selectedBlock).length}):</span>
              </div>
              {getMatchedItems(selectedBlock).length > 0 ? (
                <div className="max-h-60 overflow-y-auto space-y-1.5 pr-1">
                  {getMatchedItems(selectedBlock).slice(0, 30).map((ht) => (
                    <div key={ht.id} className="p-2 bg-white rounded border border-gray-200 hover:border-blue-300 text-xs flex justify-between items-center">
                      <div className="flex-1 pr-2">
                        <span className="font-mono font-bold text-slate-800 bg-slate-200 px-1.5 py-0.5 rounded mr-1.5 text-[10px]">
                          {ht.ma}
                        </span>
                        <span className="font-medium text-gray-800">{ht.ten}</span>
                        <div className="text-[10px] text-gray-400 mt-0.5">
                          {ht.donVi?.ten || ht.chuQuan || "Chưa xác định"} {ht.namTrienKhai ? `• Năm ${ht.namTrienKhai}` : ""}
                        </div>
                      </div>
                      <span className={`text-[10px] font-bold px-2 py-0.5 rounded border ${TRANG_THAI_CONFIG[ht.trangThai]?.badgeClass || ""}`}>
                        {TRANG_THAI_CONFIG[ht.trangThai]?.label || ht.trangThai}
                      </span>
                    </div>
                  ))}
                  {getMatchedItems(selectedBlock).length > 30 && (
                    <div className="text-center text-xs text-blue-600 py-2">
                      ...và còn {getMatchedItems(selectedBlock).length - 30} CSDL/phần mềm chuyên ngành khác.
                    </div>
                  )}
                </div>
              ) : (
                <div className="text-xs text-gray-400 italic bg-gray-50 p-2 rounded">
                  (Khối này đóng vai trò quy chuẩn mục tiêu kết nối liên thông)
                </div>
              )}
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
}

