      tasksMatch: (nv) => nv.ma === "NV-02",
      color: "#4c1d95",
      bgColor: "#f3e8ff",
      borderColor: "#e9d5ff",
    },
    lop1_mang_tslcd: {
      id: "lop1_mang_tslcd",
      title: "Mạng TSLCD Cấp I, II",
      description: "Mạng Truyền số liệu chuyên dùng cấp I, II kết nối 100% cơ quan Đảng, chính quyền 3 cấp",
      icon: <NodeIndexOutlined />,
      lop: 1,
      category: "Lớp 1: Hạ tầng số & An ninh mạng dùng chung",
      itemsMatch: (ht) => ht.ma === "HT-01" || ht.ten.toLowerCase().includes("wan") || ht.ten.toLowerCase().includes("mạng"),
      tasksMatch: (nv) => false,
      color: "#581c87",
      bgColor: "#faf5ff",
      borderColor: "#f3e8ff",
    },
    lop1_soc_anm: {
      id: "lop1_soc_anm",
      title: "SOC Tỉnh (ATTT 4 Lớp)",
      description: "Mô hình bảo vệ 4 lớp ATTT, kết nối SOC Quốc gia của Bộ Công an, chữ ký số PKI, sao lưu dự phòng",
      icon: <LockOutlined />,
      lop: 1,
      category: "Lớp 1: Hạ tầng số & An ninh mạng dùng chung",
      itemsMatch: (ht) => ht.ma === "HT-03" || ht.ten.toLowerCase().includes("soc") || ht.ten.toLowerCase().includes("an toàn"),
      tasksMatch: (nv) => nv.ma === "NV-05",
      color: "#991b1b",
      bgColor: "#fef2f2",
      borderColor: "#fecaca",
    },
    lop1_iot_bien: {
      id: "lop1_iot_bien",
      title: "Hạ Tầng IoT & Camera Biên",
      description: "Hệ thống camera giám sát an ninh đô thị, trạm quan trắc IoT môi trường, nông nghiệp",
      icon: <EyeOutlined />,
      lop: 1,
      category: "Lớp 1: Hạ tầng số & An ninh mạng dùng chung",
      itemsMatch: (ht) => ht.ten.toLowerCase().includes("camera") || ht.ten.toLowerCase().includes("quan trắc") || ht.ten.toLowerCase().includes("iot"),
      tasksMatch: (nv) => false,
      color: "#701a75",
      bgColor: "#fdf2f8",
      borderColor: "#fbcfe8",
    },
  };

  const getMatchedItems = (block: FrameworkBlock) => {
    return heThongs.filter(block.itemsMatch);
  };

  const getMatchedTasks = (block: FrameworkBlock) => {
    return nhiemVus.filter(block.tasksMatch);
  };

  // Render an ultra-clean, minimalist tile
  const renderTile = (blockKey: string) => {
    const block = frameworkBlocks[blockKey];
    if (!block) return null;
    const items = getMatchedItems(block);
    const tasks = getMatchedTasks(block);
    const hasUpgrade = items.some((i) => i.trangThai === "can-nang-cap") || tasks.length > 0;

    return (
      <div
        onClick={() => setSelectedBlock(block)}
        className="bg-white hover:bg-blue-50/60 rounded-xl px-4 py-3 border border-slate-200 hover:border-blue-500 shadow-2xs hover:shadow-md transition-all cursor-pointer flex items-center justify-between gap-2 group"
      >
        <div className="flex items-center gap-3 min-w-0">
          <div
            className="w-8 h-8 rounded-lg flex items-center justify-center text-sm shrink-0 transition-transform group-hover:scale-105 shadow-2xs"
            style={{ backgroundColor: block.bgColor, color: block.color }}
          >
            {block.icon}
          </div>
          <span className="font-bold text-slate-800 text-xs sm:text-[13px] md:text-sm group-hover:text-blue-700 transition-colors truncate">
            {block.title}
          </span>
        </div>

        <div className="flex items-center gap-1.5 shrink-0">
          {items.length > 0 && (
            <span className="text-[11px] font-semibold text-slate-600 bg-slate-100 px-2 py-0.5 rounded">
              {items.length} HT
            </span>
          )}
          {hasUpgrade && (
            <span className="w-2 h-2 rounded-full bg-amber-500 animate-pulse" title="Có nhiệm vụ lộ trình" />
          )}
          <RightOutlined className="text-[10px] text-slate-300 group-hover:text-blue-500 group-hover:translate-x-0.5 transition-all" />
        </div>
      </div>
    );
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center min-h-[60vh]">
        <Spin size="large" />
      </div>
    );
  }

  return (
    <div className="w-full space-y-5 pb-16">
      {/* Top Header Bar */}
      <div className="bg-slate-900 text-white px-6 py-4 rounded-2xl shadow-sm flex flex-col md:flex-row justify-between items-start md:items-center gap-3">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <span className="bg-blue-500/25 text-blue-300 border border-blue-400/30 text-xs px-2.5 py-0.5 rounded-full font-bold">
              QĐ 1425/QĐ-TTg • PB 1.0
            </span>
            <span className="text-xs text-slate-400">Khung Kiến Trúc Chính Quyền Số Tỉnh Vĩnh Long</span>
          </div>
          <h1 className="text-lg md:text-xl font-bold text-white m-0">
            Sơ Đồ Phân Tầng Kiến Trúc Tổng Thể (04 Lớp Chuẩn)
          </h1>
        </div>

        <div className="flex gap-2 shrink-0">
          <Link href="/kts/hien-trang">
            <Button size="small" className="bg-white/10 border-white/20 text-white hover:bg-white/20 font-medium">
              Hiện Trạng (389 HT)
            </Button>
          </Link>
          <Link href="/kts/lo-trinh">
            <Button type="primary" size="small" className="bg-blue-600 font-bold">
              Lộ Trình (9 NV)
            </Button>
          </Link>
        </div>
      </div>

      {/* ARCHITECTURE BLUEPRINT - 3 COLUMN MASTER LAYOUT */}
      <div className="bg-slate-100/70 rounded-2xl border border-slate-200 p-4 md:p-6 shadow-xs">

        <div className="grid grid-cols-1 xl:grid-cols-12 gap-4 items-stretch">

          {/* ========================================================================= */}
          {/* CỘT TRÁI: THÀNH PHẦN XUYÊN SUỐT (I & II) */}
          {/* ========================================================================= */}
          <div className="xl:col-span-2 bg-slate-200/80 rounded-xl p-3.5 flex flex-col justify-between space-y-3">
            <div className="space-y-3">
              <div className="bg-slate-800 text-white text-center font-bold text-xs md:text-sm py-2 rounded-lg shadow-xs uppercase tracking-wider">
                THÀNH PHẦN XUYÊN SUỐT
              </div>

              {/* 1. Quản trị & Thể chế */}
              <div className="bg-white p-3 rounded-xl border border-slate-300 text-center shadow-2xs">
                <BankOutlined className="text-blue-700 text-xl mb-1.5" />
                <div className="font-extrabold text-slate-900 text-xs md:text-sm">1. Quản Trị & Thể Chế</div>
                <div className="text-[11px] text-slate-500 mt-1 leading-snug">
                  Ban chỉ đạo CĐS • Kế hoạch 2026–2030 • Giám sát KPIs
                </div>
              </div>

              {/* 2. Tiêu chuẩn & Quy chuẩn */}
              <div className="bg-white p-3 rounded-xl border border-slate-300 text-center shadow-2xs">
                <SafetyCertificateOutlined className="text-blue-700 text-xl mb-1.5" />
                <div className="font-extrabold text-slate-900 text-xs md:text-sm">2. Tiêu Chuẩn & Quy Chuẩn</div>
                <div className="text-[11px] text-slate-500 mt-1 leading-snug">
                  Kiến trúc số dùng chung • Quy chế chia sẻ • Open API
                </div>
              </div>
            </div>

            <div className="text-[10px] text-slate-600 text-center font-extrabold uppercase tracking-wider pt-2 border-t border-slate-300">
              Khung Thể Chế & Chỉ Đạo
            </div>
          </div>

          {/* ========================================================================= */}
          {/* TRUNG TÂM: 04 LỚP KIẾN TRÚC CHUẨN QUỐC GIA (TOP-DOWN: LỚP 4 -> LỚP 1) */}
          {/* ========================================================================= */}
          <div className="xl:col-span-8 space-y-3.5">

            {/* ------------------------------------------------------------- */}
            {/* LỚP 4: KÊNH TƯƠNG TÁC VÀ ĐO LƯỜNG */}
            {/* ------------------------------------------------------------- */}
            <div className="bg-amber-50/70 rounded-2xl border-2 border-amber-300/80 p-3.5 shadow-2xs">

              {/* Prominent Layer Header */}
              <div className="flex flex-wrap items-center justify-between gap-2 mb-3 pb-2 border-b border-amber-300/60">
                <div className="flex items-center gap-2.5">
                  <span className="bg-amber-600 text-white font-black text-xs md:text-sm px-3 py-1 rounded-lg shadow-xs tracking-wider uppercase">
                    LỚP 4
                  </span>
                  <span className="font-extrabold text-sm md:text-base text-amber-950 uppercase tracking-wide">
                    KÊNH TƯƠNG TÁC & ĐO LƯỜNG HIỆU QUẢ
                  </span>
                </div>
                <span className="text-xs text-amber-900 font-bold bg-amber-100/90 border border-amber-300 px-3 py-0.5 rounded-full shadow-2xs">
                  Người dân • Doanh nghiệp • Cán bộ CCVC
                </span>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-2.5">
                {renderTile("lop4_dvc")}
                {renderTile("lop4_app_mobile")}
                {renderTile("lop4_portal")}
                {renderTile("lop4_kpi_metric")}
              </div>
            </div>

            {/* ------------------------------------------------------------- */}
            {/* LỚP 3: ỨNG DỤNG VÀ NGHIỆP VỤ DÙNG CHUNG */}
            {/* ------------------------------------------------------------- */}
            <div className="bg-emerald-50/60 rounded-2xl border-2 border-emerald-300/80 p-3.5 shadow-2xs space-y-3">

              {/* Prominent Layer Header */}
              <div className="flex flex-wrap items-center justify-between gap-2 mb-1 pb-2 border-b border-emerald-300/60">
                <div className="flex items-center gap-2.5">
                  <span className="bg-emerald-700 text-white font-black text-xs md:text-sm px-3 py-1 rounded-lg shadow-xs tracking-wider uppercase">
                    LỚP 3
                  </span>
                  <span className="font-extrabold text-sm md:text-base text-emerald-950 uppercase tracking-wide">
                    ỨNG DỤNG VÀ NGHIỆP VỤ DÙNG CHUNG
                  </span>
                  <span className="text-xs text-emerald-800 bg-emerald-100/90 font-bold px-2.5 py-0.5 rounded-md border border-emerald-300">
                    389+ Hệ thống
                  </span>
                </div>
                <span className="text-xs text-emerald-900 font-bold bg-emerald-100/90 border border-emerald-300 px-3 py-0.5 rounded-full shadow-2xs">
                  Tổ chức 2 Nhánh song song
                </span>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-3.5">

                {/* Nhánh 1: Chính quyền số */}
                <div className="bg-white/90 p-3 rounded-xl border border-emerald-200 space-y-2.5 shadow-2xs">
                  <div className="flex items-center justify-between px-2.5 py-1.5 bg-emerald-100/80 rounded-lg border border-emerald-200">
                    <span className="font-extrabold text-xs md:text-sm text-emerald-950 flex items-center gap-1.5">
                      🏛️ NHÁNH 1: CHÍNH QUYỀN SỐ
                    </span>
                    <span className="text-[11px] font-bold text-emerald-800 bg-white/90 px-2 py-0.5 rounded shadow-2xs">
                      Phục vụ nội bộ & TTHC
                    </span>
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                    {renderTile("lop3_chidao_dieuhanh")}
                    {renderTile("lop3_tthc_sohoa")}
                    {renderTile("lop3_ioc_tinh")}
                    {renderTile("lop3_nghiepvu_chuyennganh")}
                  </div>
                </div>

                {/* Nhánh 2: Kinh tế số & Xã hội số */}
                <div className="bg-white/90 p-3 rounded-xl border border-emerald-200 space-y-2.5 shadow-2xs">
                  <div className="flex items-center justify-between px-2.5 py-1.5 bg-emerald-100/80 rounded-lg border border-emerald-200">
                    <span className="font-extrabold text-xs md:text-sm text-emerald-950 flex items-center gap-1.5">
                      🌾 NHÁNH 2: KINH TẾ SỐ & XÃ HỘI SỐ
                    </span>
                    <span className="text-[11px] font-bold text-emerald-800 bg-white/90 px-2 py-0.5 rounded shadow-2xs">
                      Phát triển ngành & Đời sống
                    </span>
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                    {renderTile("lop3_nongnghiep_so")}
                    {renderTile("lop3_yte_so")}
                    {renderTile("lop3_datdai_tnmt")}
                    {renderTile("lop3_dothi_kinhte")}
                  </div>
                </div>
              </div>
            </div>

            {/* ------------------------------------------------------------- */}
            {/* LỚP 2: DỮ LIỆU VÀ NỀN TẢNG LÕI */}
            {/* ------------------------------------------------------------- */}
            <div className="bg-blue-50/70 rounded-2xl border-2 border-blue-300/80 p-3.5 shadow-2xs">

              {/* Prominent Layer Header */}
              <div className="flex flex-wrap items-center justify-between gap-2 mb-3 pb-2 border-b border-blue-300/60">
                <div className="flex items-center gap-2.5">
                  <span className="bg-blue-700 text-white font-black text-xs md:text-sm px-3 py-1 rounded-lg shadow-xs tracking-wider uppercase">
                    LỚP 2
                  </span>
                  <span className="font-extrabold text-sm md:text-base text-blue-950 uppercase tracking-wide">
                    DỮ LIỆU VÀ NỀN TẢNG LÕI
                  </span>
                </div>
                <span className="text-xs text-blue-900 font-bold bg-blue-100/90 border border-blue-300 px-3 py-0.5 rounded-full shadow-2xs">
                  Trục LGSP / NDXP • Kho Master Data • CSDL Quốc gia
                </span>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-2.5">
                {renderTile("lop2_lgsp_ndxp")}
                {renderTile("lop2_kho_dulieu_master")}
                {renderTile("lop2_csdl_quocgia")}
                {renderTile("lop2_nentang_loi")}
              </div>
            </div>

            {/* ------------------------------------------------------------- */}
            {/* LỚP 1: HẠ TẦNG SỐ VÀ AN NINH MẠNG */}
            {/* ------------------------------------------------------------- */}
            <div className="bg-purple-50/70 rounded-2xl border-2 border-purple-300/80 p-3.5 shadow-2xs">

              {/* Prominent Layer Header */}
              <div className="flex flex-wrap items-center justify-between gap-2 mb-3 pb-2 border-b border-purple-300/60">
                <div className="flex items-center gap-2.5">
                  <span className="bg-purple-800 text-white font-black text-xs md:text-sm px-3 py-1 rounded-lg shadow-xs tracking-wider uppercase">
                    LỚP 1
                  </span>
                  <span className="font-extrabold text-sm md:text-base text-purple-950 uppercase tracking-wide">
                    HẠ TẦNG SỐ VÀ AN NINH MẠNG DÙNG CHUNG
                  </span>
                </div>
                <span className="text-xs text-purple-900 font-bold bg-purple-100/90 border border-purple-300 px-3 py-0.5 rounded-full shadow-2xs">
                  IDC Cloud • Mạng TSLCD • Trung tâm SOC 24/7
                </span>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-2.5">
                {renderTile("lop1_idc_cloud")}
                {renderTile("lop1_mang_tslcd")}
                {renderTile("lop1_soc_anm")}
                {renderTile("lop1_iot_bien")}
              </div>
            </div>

          </div>

          {/* ========================================================================= */}
          {/* CỘT PHẢI: THÀNH PHẦN XUYÊN SUỐT (III & IV) */}
          {/* ========================================================================= */}
          <div className="xl:col-span-2 bg-indigo-100/70 rounded-xl p-3.5 flex flex-col justify-between space-y-3">
            <div className="space-y-3">
              <div className="bg-indigo-900 text-white text-center font-bold text-xs md:text-sm py-2 rounded-lg shadow-xs uppercase tracking-wider">
                THÀNH PHẦN XUYÊN SUỐT
              </div>

              {/* 3. AI First */}
              <div className="bg-white p-3 rounded-xl border border-indigo-200 text-center shadow-2xs">
                <RobotOutlined className="text-indigo-600 text-xl mb-1.5" />
                <div className="font-extrabold text-indigo-950 text-xs md:text-sm">3. Ưu Tiên AI (AI First)</div>
                <div className="text-[11px] text-slate-500 mt-1 leading-snug">
                  Trợ lý ảo CCVC & DVC • Tự động hóa quy trình
                </div>
              </div>

              {/* 4. Data-Centric */}
              <div className="bg-white p-3 rounded-xl border border-indigo-200 text-center shadow-2xs">
                <DatabaseOutlined className="text-blue-600 text-xl mb-1.5" />
                <div className="font-extrabold text-indigo-950 text-xs md:text-sm">4. Dữ Liệu Trung Tâm</div>
                <div className="text-[11px] text-slate-500 mt-1 leading-snug">
                  Đúng - Đủ - Sạch - Sống • Chia sẻ mặc định
                </div>
              </div>
            </div>

            <div className="text-[10px] text-indigo-700 text-center font-extrabold uppercase tracking-wider pt-2 border-t border-indigo-200">
              Động Lực Số & Dữ Liệu
            </div>
          </div>

        </div>
      </div>

      {/* DETAIL MODAL WHEN CLICKING ANY BLOCK */}
      <Modal
        title={
          <div className="flex items-center gap-2 pr-6">
            <span className="text-xl" style={{ color: selectedBlock?.color }}>{selectedBlock?.icon}</span>
            <span className="font-bold text-base text-gray-800">{selectedBlock?.title}</span>
          </div>
        }
        open={!!selectedBlock}
        onCancel={() => setSelectedBlock(null)}
        footer={[
          <Button key="close" type="primary" onClick={() => setSelectedBlock(null)}>
            Đóng
          </Button>,
        ]}
        width={750}
        destroyOnHidden
      >
        {selectedBlock && (
          <div className="space-y-4 mt-3">
            <div className="bg-slate-50 p-3 rounded-lg border border-slate-200 text-xs text-gray-700 leading-relaxed">
              <b>Phân loại kiến trúc:</b> <Tag color="blue">{selectedBlock.category}</Tag>
              <div className="mt-1">{selectedBlock.description}</div>
            </div>

            {/* Nhiệm vụ lộ trình liên quan */}
            <div>
              <div className="font-bold text-gray-800 text-sm mb-2 flex items-center gap-1.5">
                <ThunderboltOutlined className="text-amber-500" />
                <span>Nhiệm vụ & Đề án Lộ trình liên quan ({getMatchedTasks(selectedBlock).length}):</span>
              </div>
              {getMatchedTasks(selectedBlock).length > 0 ? (
                <div className="space-y-2">
                  {getMatchedTasks(selectedBlock).map((nv) => (
                    <div key={nv.id} className="p-3 bg-amber-50/60 rounded-lg border border-amber-200 flex justify-between items-center">
                      <div>
                        <div className="font-semibold text-gray-800 text-xs">
                          <span className="font-mono bg-amber-100 text-amber-800 px-1.5 py-0.5 rounded mr-1.5">{nv.ma}</span>
                          {nv.ten}
                        </div>
                        <div className="text-[11px] text-gray-500 mt-1">
                          Chủ trì: {nv.donViChuTri?.ten || "UBND tỉnh"} • Hạn: {nv.thoiHan ? new Date(nv.thoiHan).toLocaleDateString("vi-VN") : "—"}
                        </div>
                      </div>
                      <span className="font-bold text-xs text-blue-600 bg-white px-2 py-1 rounded border border-blue-200">
                        {nv.tienDo}%
                      </span>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-xs text-gray-400 italic bg-gray-50 p-2 rounded">
                  (Khối này hiện đang vận hành ổn định, không có dự án nâng cấp quy mô lớn trong lộ trình hiện tại)
                </div>
              )}
            </div>

            {/* Danh sách hệ thống số hiện trạng */}
            <div>
              <div className="font-bold text-gray-800 text-sm mb-2 flex items-center gap-1.5">
                <DatabaseOutlined className="text-blue-500" />
                <span>Hệ thống số & CSDL Hiện trạng thuộc khối này ({getMatchedItems(selectedBlock).length}):</span>
              </div>
              {getMatchedItems(selectedBlock).length > 0 ? (
                <div className="max-h-60 overflow-y-auto space-y-1.5 pr-1">
                  {getMatchedItems(selectedBlock).slice(0, 30).map((ht) => (
                    <div key={ht.id} className="p-2 bg-white rounded border border-gray-200 hover:border-blue-300 text-xs flex justify-between items-center">
                      <div className="flex-1 pr-2">
                        <span className="font-mono font-bold text-slate-800 bg-slate-200 px-1.5 py-0.5 rounded mr-1.5 text-[10px]">
                          {ht.ma}
                        </span>
                        <span className="font-medium text-gray-800">{ht.ten}</span>
                        <div className="text-[10px] text-gray-400 mt-0.5">
                          {ht.donVi?.ten || ht.chuQuan || "Chưa xác định"} {ht.namTrienKhai ? `• Năm ${ht.namTrienKhai}` : ""}
                        </div>
                      </div>
                      <span className={`text-[10px] font-bold px-2 py-0.5 rounded border ${TRANG_THAI_CONFIG[ht.trangThai]?.badgeClass || ""}`}>
                        {TRANG_THAI_CONFIG[ht.trangThai]?.label || ht.trangThai}
                      </span>
                    </div>
                  ))}
                  {getMatchedItems(selectedBlock).length > 30 && (
                    <div className="text-center text-xs text-blue-600 py-2">
                      ...và còn {getMatchedItems(selectedBlock).length - 30} CSDL/phần mềm chuyên ngành khác.
                    </div>
                  )}
                </div>
              ) : (
                <div className="text-xs text-gray-400 italic bg-gray-50 p-2 rounded">
                  (Khối này đóng vai trò quy chuẩn mục tiêu kết nối liên thông)
                </div>
              )}
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
}

