"use client";
import { useState, useEffect } from "react";
import Link from "next/link";
import { Tag, Modal, Button, Spin } from "antd";
import {
  ApartmentOutlined,
  DatabaseOutlined,
  GlobalOutlined,
  BankOutlined,
  SafetyCertificateOutlined,
  ThunderboltOutlined,
  RightOutlined,
  FileProtectOutlined,
  CloudServerOutlined,
  MobileOutlined,
  NodeIndexOutlined,
  LockOutlined,
  DesktopOutlined,
  TeamOutlined,
  FundProjectionScreenOutlined,
  RobotOutlined,
  DeploymentUnitOutlined,
  AuditOutlined,
  SlidersOutlined,
  ShopOutlined,
  MedicineBoxOutlined,
  EnvironmentOutlined,
  EyeOutlined,
  CompassOutlined,
} from "@ant-design/icons";
import { HeThongSoData, NhiemVuData } from "@/types";
import { TRANG_THAI_CONFIG } from "@/lib/utils";

interface FrameworkBlock {
  id: string;
  title: string;
  description: string;
  icon: React.ReactNode;
  lop: number;
  category: string;
  itemsMatch: (ht: HeThongSoData) => boolean;
  tasksMatch: (nv: NhiemVuData) => boolean;
  color: string;
  bgColor: string;
  borderColor: string;
}

export default function SoDoKhungKTSPage() {
  const [heThongs, setHeThongs] = useState<HeThongSoData[]>([]);
  const [nhiemVus, setNhiemVus] = useState<NhiemVuData[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedBlock, setSelectedBlock] = useState<FrameworkBlock | null>(null);

  useEffect(() => {
    Promise.all([
      fetch("/api/he-thong").then((r) => r.json()),
      fetch("/api/nhiem-vu").then((r) => r.json()),
    ])
      .then(([htData, nvData]) => {
        setHeThongs(Array.isArray(htData) ? htData : []);
        setNhiemVus(Array.isArray(nvData) ? nvData : []);
        setLoading(false);
      })
      .catch(() => {
        setHeThongs([]);
        setNhiemVus([]);
        setLoading(false);
      });
  }, []);

  // 4 Standard Layers according to Decision 1425/QĐ-TTg (Version 1.0)
  const frameworkBlocks: Record<string, FrameworkBlock> = {
    // ==========================================
    // LỚP 4: KÊNH TƯƠNG TÁC VÀ ĐO LƯỜNG HIỆU QUẢ
    // ==========================================
    lop4_dvc: {
      id: "lop4_dvc",
      title: "Cổng DVC & Một Cửa",
      description: "Cổng Dịch vụ công trực tuyến tỉnh tích hợp kết nối Cổng DVC Quốc gia và Hệ thống Một cửa điện tử",
      icon: <GlobalOutlined />,
      lop: 4,
      category: "Lớp 4: Kênh tương tác & Đo lường",
      itemsMatch: (ht) => ht.lop === 4 || ht.ten.toLowerCase().includes("dịch vụ công") || ht.ten.toLowerCase().includes("một cửa"),
      tasksMatch: (nv) => nv.ma === "NV-04" || nv.lop === 4,
      color: "#ea580c",
      bgColor: "#fff7ed",
      borderColor: "#fed7aa",
    },
    lop4_app_mobile: {
      id: "lop4_app_mobile",
      title: "App Vĩnh Long Smart",
      description: "Ứng dụng công dân số đa tiện ích, tích hợp Zalo Mini App và tài khoản định danh điện tử VNeID",
      icon: <MobileOutlined />,
      lop: 4,
      category: "Lớp 4: Kênh tương tác & Đo lường",
      itemsMatch: (ht) => ht.ten.toLowerCase().includes("di động") || ht.ten.toLowerCase().includes("app") || ht.ten.toLowerCase().includes("smart") || ht.ma === "DL-01",
      tasksMatch: (nv) => nv.ma === "NV-07" || nv.ma === "NV-03",
      color: "#ea580c",
      bgColor: "#fff7ed",
      borderColor: "#fed7aa",
    },
    lop4_portal: {
      id: "lop4_portal",
      title: "Cổng Thông Tin Tỉnh",
      description: "Hệ thống Cổng thông tin điện tử tỉnh và các trang thành phần của các Sở, Ban, Ngành, UBND cấp huyện",
      icon: <ApartmentOutlined />,
      lop: 4,
      category: "Lớp 4: Kênh tương tác & Đo lường",
      itemsMatch: (ht) => ht.ten.toLowerCase().includes("cổng thông tin") || ht.ten.toLowerCase().includes("portal"),
      tasksMatch: (nv) => false,
      color: "#ea580c",
      bgColor: "#fff7ed",
      borderColor: "#fed7aa",
    },
    lop4_kpi_metric: {
      id: "lop4_kpi_metric",
      title: "Dashboard Đo Lường KPI",
      description: "Hệ thống giám sát, đo lường mức độ hài lòng, tỷ lệ DVC trực tuyến toàn trình và KPIs phục vụ người dân, doanh nghiệp",
      icon: <FundProjectionScreenOutlined />,
      lop: 4,
      category: "Lớp 4: Kênh tương tác & Đo lường",
      itemsMatch: (ht) => ht.ten.toLowerCase().includes("đo lường") || ht.ten.toLowerCase().includes("kpi") || ht.ten.toLowerCase().includes("đánh giá"),
      tasksMatch: (nv) => nv.ma === "NV-04",
      color: "#ea580c",
      bgColor: "#fff7ed",
      borderColor: "#fed7aa",
    },

    // =========================================================================
    // LỚP 3: ỨNG DỤNG VÀ NGHIỆP VỤ DÙNG CHUNG
    // =========================================================================
    // Nhánh 1: Chính quyền số
    lop3_chidao_dieuhanh: {
      id: "lop3_chidao_dieuhanh",
      title: "Chỉ Đạo & Điều Hành",
      description: "Quản lý văn bản điều hành iOffice, phòng họp không giấy e-Cabinet, hệ thống thông tin báo cáo tỉnh",
      icon: <FileProtectOutlined />,
      lop: 3,
      category: "Lớp 3: Chính quyền số (Nội bộ & TTHC)",
      itemsMatch: (ht) => ht.ten.toLowerCase().includes("văn bản") || ht.ten.toLowerCase().includes("điều hành") || ht.ten.toLowerCase().includes("báo cáo"),
      tasksMatch: (nv) => nv.ten.toLowerCase().includes("văn bản"),
      color: "#16a34a",
      bgColor: "#f0fdf4",
      borderColor: "#bbf7d0",
    },
    lop3_tthc_sohoa: {
      id: "lop3_tthc_sohoa",
      title: "Giải Quyết TTHC",
      description: "Quy trình giải quyết TTHC liên thông, số hóa hồ sơ và trả kết quả bản điện tử toàn tỉnh",
      icon: <DesktopOutlined />,
      lop: 3,
      category: "Lớp 3: Chính quyền số (Nội bộ & TTHC)",
      itemsMatch: (ht) => ht.ten.toLowerCase().includes("thủ tục") || ht.ten.toLowerCase().includes("tthc"),
      tasksMatch: (nv) => nv.ma === "NV-04",
      color: "#16a34a",
      bgColor: "#f0fdf4",
      borderColor: "#bbf7d0",
    },
    lop3_ioc_tinh: {
      id: "lop3_ioc_tinh",
      title: "Trung Tâm IOC Tỉnh",
      description: "Trung tâm Giám sát, Điều hành thông minh tỉnh Vĩnh Long kết nối dữ liệu liên ngành phục vụ lãnh đạo",
      icon: <FundProjectionScreenOutlined />,
      lop: 3,
      category: "Lớp 3: Chính quyền số (Nội bộ & TTHC)",
      itemsMatch: (ht) => ht.ten.toLowerCase().includes("ioc") || ht.ten.toLowerCase().includes("điều hành thông minh"),
      tasksMatch: (nv) => nv.ma === "NV-08",
      color: "#16a34a",
      bgColor: "#f0fdf4",
      borderColor: "#bbf7d0",
    },
    lop3_nghiepvu_chuyennganh: {
      id: "lop3_nghiepvu_chuyennganh",
      title: "Nghiệp Vụ Sở Ngành",
      description: "Phần mềm nghiệp vụ quản lý cán bộ công chức, tư pháp hộ tịch, thanh tra, tài chính ngân sách",
      icon: <AuditOutlined />,
      lop: 3,
      category: "Lớp 3: Chính quyền số (Nội bộ & TTHC)",
      itemsMatch: (ht) => (ht.lop === 3 && !ht.ma.startsWith("SNN-") && ht.ma !== "UD-03") || ht.ten.toLowerCase().includes("cán bộ"),
      tasksMatch: (nv) => false,
      color: "#16a34a",
      bgColor: "#f0fdf4",
      borderColor: "#bbf7d0",
    },

    // Nhánh 2: Kinh tế số & Xã hội số
    lop3_nongnghiep_so: {
      id: "lop3_nongnghiep_so",
      title: "Nông Nghiệp (380+ CSDL)",
      description: "Bản đồ số canh tác, trạm quan trắc VnEmisoft, CSDL trồng trọt, chăn nuôi, thủy sản, OCOP, truy xuất nguồn gốc",
      icon: <ShopOutlined />,
      lop: 3,
      category: "Lớp 3: Kinh tế số & Xã hội số",
      itemsMatch: (ht) => ht.ma.startsWith("SNN-") || (ht.donVi?.ten || "").includes("Nông nghiệp"),
      tasksMatch: (nv) => false,
      color: "#059669",
      bgColor: "#ecfdf5",
      borderColor: "#a7f3d0",
    },
    lop3_yte_so: {
      id: "lop3_yte_so",
      title: "Y Tế & Sức Khỏe Số",
      description: "Quản lý bệnh viện HIS, Bệnh án điện tử EMR, quản lý trạm y tế xã phường, hồ sơ sức khỏe điện tử",
      icon: <MedicineBoxOutlined />,
      lop: 3,
      category: "Lớp 3: Kinh tế số & Xã hội số",
      itemsMatch: (ht) => ht.ma === "UD-03" || ht.ten.toLowerCase().includes("y tế") || ht.ten.toLowerCase().includes("his"),
      tasksMatch: (nv) => nv.ma === "NV-09",
      color: "#059669",
      bgColor: "#ecfdf5",
      borderColor: "#a7f3d0",
    },
    lop3_datdai_tnmt: {
      id: "lop3_datdai_tnmt",
      title: "Đất Đai & Môi Trường",
      description: "CSDL Đất đai tỉnh kết nối nền tảng điều phối dữ liệu đất đai quốc gia (NDOP), quan trắc môi trường",
      icon: <EnvironmentOutlined />,
      lop: 3,
      category: "Lớp 3: Kinh tế số & Xã hội số",
      itemsMatch: (ht) => ht.ma === "DL-02" || ht.ten.toLowerCase().includes("đất đai") || ht.ten.toLowerCase().includes("môi trường"),
      tasksMatch: (nv) => nv.ma === "NV-01",
      color: "#059669",
      bgColor: "#ecfdf5",
      borderColor: "#a7f3d0",
    },
    lop3_dothi_kinhte: {
      id: "lop3_dothi_kinhte",
      title: "Đô Thị, Du Lịch & GD",
      description: "Cổng du lịch thông minh, giáo dục số, chiếu sáng/giao thông thông minh, thương mại điện tử",
      icon: <CompassOutlined />,
      lop: 3,
      category: "Lớp 3: Kinh tế số & Xã hội số",
      itemsMatch: (ht) => ht.ten.toLowerCase().includes("du lịch") || ht.ten.toLowerCase().includes("giáo dục") || ht.ten.toLowerCase().includes("thương mại"),
      tasksMatch: (nv) => false,
      color: "#059669",
      bgColor: "#ecfdf5",
      borderColor: "#a7f3d0",
    },

    // ==========================================
    // LỚP 2: DỮ LIỆU VÀ NỀN TẢNG LÕI
    // ==========================================
    lop2_lgsp_ndxp: {
      id: "lop2_lgsp_ndxp",
      title: "Trục LGSP / NDXP",
      description: "Nền tảng tích hợp, chia sẻ dữ liệu cấp tỉnh (LGSP) liên thông Trục Quốc gia (NDXP)",
      icon: <NodeIndexOutlined />,
      lop: 2,
      category: "Lớp 2: Dữ liệu & Nền tảng lõi",
      itemsMatch: (ht) => ht.ma === "DL-03" || ht.ten.toLowerCase().includes("lgsp") || ht.ten.toLowerCase().includes("chia sẻ"),
      tasksMatch: (nv) => nv.ma === "NV-04" || nv.ma === "NV-06",
      color: "#2563eb",
      bgColor: "#eff6ff",
      borderColor: "#bfdbfe",
    },
    lop2_kho_dulieu_master: {
      id: "lop2_kho_dulieu_master",
      title: "Kho Dữ Liệu Tỉnh",
      description: "Kho dữ liệu tổng hợp tỉnh, từ điển danh mục dùng chung và nền tảng dữ liệu mở (Open Data)",
      icon: <DatabaseOutlined />,
      lop: 2,
      category: "Lớp 2: Dữ liệu & Nền tảng lõi",
      itemsMatch: (ht) => ht.ma.startsWith("DL-") || ht.ten.toLowerCase().includes("kho dữ liệu") || ht.ten.toLowerCase().includes("danh mục"),
      tasksMatch: (nv) => nv.ma === "NV-06",
      color: "#2563eb",
      bgColor: "#eff6ff",
      borderColor: "#bfdbfe",
    },
    lop2_csdl_quocgia: {
      id: "lop2_csdl_quocgia",
      title: "CSDL Quốc Gia (Đề án 06)",
      description: "Kết nối CSDL Quốc gia về Dân cư, CSDL Đất đai, CSDL Đăng ký doanh nghiệp, Bảo hiểm xã hội",
      icon: <ApartmentOutlined />,
      lop: 2,
      category: "Lớp 2: Dữ liệu & Nền tảng lõi",
      itemsMatch: (ht) => ht.ten.toLowerCase().includes("dân cư") || ht.ma === "DL-01" || ht.ma === "DL-02",
      tasksMatch: (nv) => nv.ma === "NV-03" || nv.ma === "NV-01",
      color: "#2563eb",
      bgColor: "#eff6ff",
      borderColor: "#bfdbfe",
    },
    lop2_nentang_loi: {
      id: "lop2_nentang_loi",
      title: "Định Danh VNeID & GIS",
      description: "Nền tảng xác thực định danh (VNeID/SSO), Nền tảng thanh toán số Payment, Nền tảng Bản đồ số GIS",
      icon: <DeploymentUnitOutlined />,
      lop: 2,
      category: "Lớp 2: Dữ liệu & Nền tảng lõi",
      itemsMatch: (ht) => ht.ten.toLowerCase().includes("định danh") || ht.ten.toLowerCase().includes("gis") || ht.ten.toLowerCase().includes("thanh toán"),
      tasksMatch: (nv) => nv.ma === "NV-03",
      color: "#2563eb",
      bgColor: "#eff6ff",
      borderColor: "#bfdbfe",
    },

    // ==========================================
    // LỚP 1: HẠ TẦNG SỐ VÀ AN NINH MẠNG DÙNG CHUNG
    // ==========================================
    lop1_idc_cloud: {
      id: "lop1_idc_cloud",
      title: "Trung Tâm Dữ Liệu (IDC)",
      description: "Trung tâm tích hợp dữ liệu tỉnh, chuyển đổi sang kiến trúc Cloud kết nối Cloud Quốc gia",
      icon: <CloudServerOutlined />,
      lop: 1,
      category: "Lớp 1: Hạ tầng số & An ninh mạng dùng chung",
      itemsMatch: (ht) => ht.ma === "HT-02" || ht.ten.toLowerCase().includes("idc") || ht.ten.toLowerCase().includes("trung tâm tích hợp"),
      tasksMatch: (nv) => nv.ma === "NV-02",
      color: "#7c3aed",
      bgColor: "#f5f3ff",
      borderColor: "#ddd6fe",
    },
    lop1_mang_tslcd: {
      id: "lop1_mang_tslcd",
      title: "Mạng TSLCD Cấp I, II",
      description: "Mạng Truyền số liệu chuyên dùng cấp I, II kết nối 100% cơ quan Đảng, chính quyền 3 cấp",
      icon: <NodeIndexOutlined />,
      lop: 1,
      category: "Lớp 1: Hạ tầng số & An ninh mạng dùng chung",
      itemsMatch: (ht) => ht.ma === "HT-01" || ht.ten.toLowerCase().includes("wan") || ht.ten.toLowerCase().includes("mạng"),
      tasksMatch: (nv) => false,
      color: "#7c3aed",
      bgColor: "#f5f3ff",
      borderColor: "#ddd6fe",
    },
    lop1_soc_anm: {
      id: "lop1_soc_anm",
      title: "SOC Tỉnh (ATTT 4 Lớp)",
      description: "Mô hình bảo vệ 4 lớp ATTT, kết nối SOC Quốc gia của Bộ Công an, chữ ký số PKI, sao lưu dự phòng",
      icon: <LockOutlined />,
      lop: 1,
      category: "Lớp 1: Hạ tầng số & An ninh mạng dùng chung",
      itemsMatch: (ht) => ht.ma === "HT-03" || ht.ten.toLowerCase().includes("soc") || ht.ten.toLowerCase().includes("an toàn"),
      tasksMatch: (nv) => nv.ma === "NV-05",
      color: "#7c3aed",
      bgColor: "#f5f3ff",
      borderColor: "#ddd6fe",
    },
    lop1_iot_bien: {
      id: "lop1_iot_bien",
      title: "Hạ Tầng IoT & Camera",
      description: "Hệ thống camera giám sát an ninh đô thị, trạm quan trắc IoT môi trường, nông nghiệp",
      icon: <EyeOutlined />,
      lop: 1,
      category: "Lớp 1: Hạ tầng số & An ninh mạng dùng chung",
      itemsMatch: (ht) => ht.ten.toLowerCase().includes("camera") || ht.ten.toLowerCase().includes("quan trắc") || ht.ten.toLowerCase().includes("iot"),
      tasksMatch: (nv) => false,
      color: "#7c3aed",
      bgColor: "#f5f3ff",
      borderColor: "#ddd6fe",
    },
  };

  const getMatchedItems = (block: FrameworkBlock) => {
    return heThongs.filter(block.itemsMatch);
  };

  const getMatchedTasks = (block: FrameworkBlock) => {
    return nhiemVus.filter(block.tasksMatch);
  };

  // Render a clean architectural block (tile)
  const renderTile = (blockKey: string) => {
    const block = frameworkBlocks[blockKey];
    if (!block) return null;
    const items = getMatchedItems(block);
    const tasks = getMatchedTasks(block);
    const hasUpgrade = items.some((i) => i.trangThai === "can-nang-cap") || tasks.length > 0;

    return (
      <div
        onClick={() => setSelectedBlock(block)}
        className="bg-white hover:bg-slate-50 rounded-xl px-3.5 py-3 border border-slate-200 hover:border-blue-500 shadow-xs hover:shadow-md transition-all cursor-pointer flex items-center justify-between gap-2 group"
      >
        <div className="flex items-center gap-2.5 min-w-0">
          <div
            className="w-8 h-8 rounded-lg flex items-center justify-center text-sm shrink-0 transition-transform group-hover:scale-105"
            style={{ backgroundColor: block.bgColor, color: block.color }}
          >
            {block.icon}
          </div>
          <span className="font-bold text-slate-800 text-xs sm:text-[13px] group-hover:text-blue-700 transition-colors truncate">
            {block.title}
          </span>
        </div>

        <div className="flex items-center gap-1.5 shrink-0">
          {items.length > 0 && (
            <span className="text-[11px] font-semibold text-slate-500 bg-slate-100 px-2 py-0.5 rounded">
              {items.length}
            </span>
          )}
          {hasUpgrade && (
            <span className="w-2 h-2 rounded-full bg-amber-500 animate-pulse" title="Có nhiệm vụ lộ trình" />
          )}
          <RightOutlined className="text-[10px] text-slate-300 group-hover:text-blue-500" />
        </div>
      </div>
    );
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center min-h-[60vh]">
        <Spin size="large" />
      </div>
    );
  }

  return (
    <div className="w-full space-y-5 pb-16">

      {/* Header Bar */}
      <div className="bg-gradient-to-r from-slate-900 to-blue-950 text-white px-6 py-4 rounded-2xl shadow-sm flex flex-col md:flex-row justify-between items-start md:items-center gap-3">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <span className="bg-blue-500/30 text-blue-200 border border-blue-400/40 text-xs px-2.5 py-0.5 rounded-full font-bold">
